{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Piritrexim, the closest analogue (Morgan 0.2809), shares the 2,4-diaminopyrimidine and dimethoxybenzyl pharmacophore; its oral bioavailability in patients is ~75%, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Trimazosin, a 2-aminoquinazoline with trimethoxybenzene, has oral bioavailability 63 ± 25% in humans; the shared aminopyrimidine/quinazoline and methoxyaromatic features support high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Abecarnil, a heteroaromatic indole-containing drug with an ester/carboxamide and lipophilic substituents, has absolute oral bioavailability 39 ± 17% in healthy volunteers, supporting that the query's complex heteroaromatic scaffold can still achieve F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "GSK269984A, despite a low physicochemical prior and predicted ~10% F, showed 95% absolute oral bioavailability in humans, demonstrating that lipophilic/poor-solubility molecules can be well absorbed and overriding prior-based low predictions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Alfuzosin, a dimethoxyquinazoline with a basic side chain, has 49% absolute oral bioavailability under fed conditions, supporting high F for the query's related aminopyrimidine/dimethoxyarene system.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Betrixaban, a high-MW polar oral drug, has 34% absolute oral bioavailability in humans, showing that even challenging physicochemical profiles can meet the F ≥ 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Alisertib, a complex heteroaromatic kinase inhibitor with methoxy/chlorophenyl substituents, has F = 0.671 in pediatric patients, supporting high oral bioavailability for the similarly complex query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Although the physicochemical prior is low, all transferable experimental analogues show absolute oral bioavailability ≥ 20%, mostly 34–95%, including the closest analogue piritrexim (~75%) and structurally related quinazoline/heteroaromatic drugs. The consistent experimental direction outweighs the uncertain prior, so the query is predicted high for F ≥ 20%.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data exist for the query molecule.",
    "Morgan similarities to the closest analogues are modest (0.20–0.28), limiting exact transferability.",
    "The query's high molecular weight, high TPSA, and low solubility may reduce absorption in practice, but no direct counter-evidence supports F < 20%.",
    "Metabolic stability and transporter effects for the query are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

